BEGIN;
CREATE TABLE IF NOT EXISTS mission_bridge_experiments(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id TEXT NOT NULL,program_id TEXT NOT NULL,name TEXT NOT NULL,hypothesis TEXT NOT NULL,primary_metric TEXT NOT NULL,secondary_metrics JSONB NOT NULL DEFAULT '[]'::jsonb,high_risk_group BOOLEAN NOT NULL DEFAULT FALSE,safeguarding_review_status TEXT NOT NULL DEFAULT 'not_required',research_disclosure TEXT NOT NULL,basic_care_unaffected BOOLEAN NOT NULL DEFAULT TRUE,coercive_messaging BOOLEAN NOT NULL DEFAULT FALSE,status TEXT NOT NULL DEFAULT 'draft',created_by TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),CHECK(basic_care_unaffected=TRUE),CHECK(coercive_messaging=FALSE),CHECK(primary_metric<>'conversion_rate' OR jsonb_array_length(secondary_metrics)>0));
CREATE TABLE IF NOT EXISTS mission_bridge_experiment_assignments(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id TEXT NOT NULL,experiment_id UUID NOT NULL REFERENCES mission_bridge_experiments(id),anonymous_subject_hash TEXT NOT NULL,variant TEXT NOT NULL,research_disclosed BOOLEAN NOT NULL DEFAULT FALSE,assigned_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(experiment_id,anonymous_subject_hash));
CREATE TABLE IF NOT EXISTS mission_bridge_analytics_events(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id TEXT NOT NULL,anonymous_subject_hash TEXT NOT NULL,program_id TEXT,event_type TEXT NOT NULL,medium TEXT,time_bucket TEXT,group_segment TEXT,metadata JSONB NOT NULL DEFAULT '{}'::jsonb,occurred_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS mission_bridge_analysis_runs(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id TEXT NOT NULL,analysis_type TEXT NOT NULL CHECK(analysis_type IN('cohort','step_funnel','exit_reasons','medium_effect','time_effect','group_difference','safety_trend','content_quality','mentor_capacity','referral_closure')),parameters JSONB NOT NULL,result JSONB NOT NULL,minimum_cell_size INTEGER NOT NULL DEFAULT 5,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
DO $$ DECLARE t TEXT; BEGIN FOREACH t IN ARRAY ARRAY['mission_bridge_experiments','mission_bridge_experiment_assignments','mission_bridge_analytics_events','mission_bridge_analysis_runs'] LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('CREATE POLICY tenant_isolation ON %I USING (tenant_id=current_setting(''app.tenant_id'',true)) WITH CHECK (tenant_id=current_setting(''app.tenant_id'',true))',t);END LOOP;END $$;
COMMIT;
